count['id']) ?>">Role</label><select class="form-select" name="role_id" id="role-<?= e($account['id']) ?>"><option value="2" <?= $account['role_id']==2?'selected':'' ?>>Publisher</option><option value="1" <?= $account['role_id']==1?'selected':'' ?>>Administrator</option></select></div><div class="col-md-1"><label class="form-check mb-2"><input class="form-check-input" name="is_active" type="checkbox" <?= $account['is_active']?'checked':'' ?>><span class="form-check-label">Active</span></label></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100" type="submit" <?= $account['id']===$user['id']?'disabled':'' ?>><?= $account['id']===$user['id']?'Your account':'Save access' ?></button></div></form></section><?php endforeach; ?>
